app_css:
.tool-app-meeting-cost { max-width: 640px; color: #451a03; }
.tool-app-meeting-cost .mc-ticker-wrap { background: #fffbeb; border: 2px solid #f59e0b; border-radius: 16px; padding: 20px; text-align: center; margin-bottom: 14px; }
.tool-app-meeting-cost .mc-ticker-label { font-size: 13px; font-weight: 600; color: #92400e; }
.tool-app-meeting-cost .mc-ticker { font-size: 44px; font-weight: 800; color: #b45309; font-variant-numeric: tabular-nums; }
.tool-app-meeting-cost .mc-elapsed { font-size: 16px; color: #92400e; font-variant-numeric: tabular-nums; }
.tool-app-meeting-cost .mc-controls { display: flex; gap: 8px; align-items: flex-end; flex-wrap: wrap; margin-bottom: 14px; }
.tool-app-meeting-cost .mc-btn { background: #f59e0b; color: #fff; border: none; border-radius: 10px; padding: 9px 16px; font-weight: 700; cursor: pointer; }
.tool-app-meeting-cost .mc-btn:hover { background: #d97706; }
.tool-app-meeting-cost .mc-btn-ghost { background: #fef3c7; color: #92400e; }
.tool-app-meeting-cost .mc-btn-ghost:hover { background: #fde68a; }
.tool-app-meeting-cost .mc-min { display: flex; flex-direction: column; font-size: 12px; font-weight: 600; gap: 4px; }
.tool-app-meeting-cost .mc-min input { border: 1px solid #fcd34d; border-radius: 8px; padding: 8px; width: 90px; }
.tool-app-meeting-cost .mc-row { display: flex; gap: 8px; align-items: center; margin-bottom: 8px; flex-wrap: wrap; }
.tool-app-meeting-cost .mc-row .mc-name { flex: 1; min-width: 110px; border: 1px solid #fcd34d; border-radius: 8px; padding: 8px; }
.tool-app-meeting-cost .mc-ratewrap { display: flex; align-items: center; gap: 2px; font-size: 14px; }
.tool-app-meeting-cost .mc-row .mc-rate { width: 64px; border: 1px solid #fcd34d; border-radius: 8px; padding: 8px; }
.tool-app-meeting-cost .mc-presets button { border: 1px solid #fcd34d; background: #fff; border-radius: 6px; padding: 4px 8px; font-size: 12px; cursor: pointer; margin-right: 4px; }
.tool-app-meeting-cost .mc-presets button:hover { background: #fef3c7; }
.tool-app-meeting-cost .mc-rowcost { font-weight: 700; min-width: 70px; text-align: right; font-variant-numeric: tabular-nums; }
.tool-app-meeting-cost .mc-del { background: none; border: none; color: #b91c1c; font-size: 20px; cursor: pointer; }

app_js:
(function () {
  'use strict';
  function $(id) { return document.getElementById(id); }
  function esc(s) {
    return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  }
  function money(n) { return '$' + (isFinite(n) ? n : 0).toFixed(2); }
  function fmt(s) {
    s = Math.max(0, Math.floor(s));
    function p(x) { return (x < 10 ? '0' : '') + x; }
    return p(Math.floor(s / 3600)) + ':' + p(Math.floor((s % 3600) / 60)) + ':' + p(s % 60);
  }
  var list = $('mc-attendees');
  var elapsed = 0;
  var timer = null;
  function addAttendee(name, rate) {
    var row = document.createElement('div');
    row.className = 'mc-row';
    var presets = [25, 50, 100, 150, 250].map(function (r) {
      return '<button type="button" data-rate="' + r + '">$' + r + '</button>';
    }).join('');
    row.innerHTML =
      '<input type="text" class="mc-name" placeholder="Name" value="' + esc(name) + '">' +
      '<span class="mc-ratewrap">$<input type="number" class="mc-rate" min="0" step="1" value="' + (rate == null ? 100 : rate) + '">/hr</span>' +
      '<span class="mc-presets">' + presets + '</span>' +
      '<span class="mc-rowcost">$0.00</span>' +
      '<button type="button" class="mc-del" aria-label="Remove attendee">×</button>';
    list.appendChild(row);
    tick();
  }
  function tick() {
    var total = 0;
    var rows = list.querySelectorAll('.mc-row');
    for (var i = 0; i < rows.length; i++) {
      var rate = parseFloat(rows[i].querySelector('.mc-rate').value) || 0;
      var cost = (rate / 3600) * elapsed;
      total += cost;
      rows[i].querySelector('.mc-rowcost').textContent = money(cost);
    }
    $('mc-ticker').textContent = money(total);
    $('mc-elapsed').textContent = fmt(elapsed);
  }
  function start() {
    if (timer) return;
    timer = setInterval(function () { elapsed += 1; tick(); }, 1000);
  }
  function pause() {
    if (timer) { clearInterval(timer); timer = null; }
  }
  list.addEventListener('input', function () { tick(); });
  list.addEventListener('click', function (e) {
    var t = e.target;
    if (t.classList && t.classList.contains('mc-del')) { t.closest('.mc-row').remove(); tick(); return; }
    var r = t.getAttribute ? t.getAttribute('data-rate') : null;
    if (r) {
      var row = t.closest('.mc-row');
      if (row) { row.querySelector('.mc-rate').value = r; tick(); }
    }
  });
  $('mc-add').addEventListener('click', function () { addAttendee('', 100); });
  $('mc-start').addEventListener('click', start);
  $('mc-pause').addEventListener('click', pause);
  $('mc-reset').addEventListener('click', function () { pause(); elapsed = 0; $('mc-minutes').value = 0; tick(); });
  $('mc-minutes').addEventListener('change', function () {
    var m = Math.max(0, parseFloat($('mc-minutes').value) || 0);
    elapsed = Math.round(m * 60);
    tick();
  });
  addAttendee('You', 100);
  addAttendee('Teammate', 75);
  tick();
})();
